def parse_roman(s):
    if not isinstance(s, str) or not s:
        return None

    values = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'),
        (1, 'I')
    ]

    def to_roman(n):
        result = []
        for val, sym in values:
            while n >= val:
                result.append(sym)
                n -= val
        return ''.join(result)

    for n in range(1, 4000):
        if to_roman(n) == s:
            return n
    return None

